-- Explicações por artigo — Lei Maria da Penha (Lei nº 11.340, de 2006). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do art. 226, §8º, da Constituição, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana de Belém do Pará e de outros tratados ratificados pelo Brasil. Dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher e estabelece medidas de assistência e proteção às mulheres em situação de violência.', '["Coibir e prevenir a violência doméstica e familiar contra a mulher.","Fundamento constitucional e em tratados internacionais.","Criação dos Juizados de Violência Doméstica e Familiar.","Medidas de assistência e proteção."]'::jsonb, '["A lei é de natureza mista: penal, processual, civil e de assistência.","Parâmetros internacionais: Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher e Convenção de Belém do Pará."]'::jsonb, 'A mulher agredida pelo companheiro recebe proteção por medidas urgentes e atendimento no Juizado especializado.', '["Assertiva que restringe a Lei Maria da Penha ao aspecto penal, sem medidas de assistência e proteção, erra."]'::jsonb, '[]'::jsonb, '["Art. 5º","Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social.', '["Proteção a toda mulher, sem distinção de classe, raça, etnia, orientação sexual, renda, cultura, instrução, idade ou religião.","Direito de viver sem violência e de preservar a saúde física e mental."]'::jsonb, '["A lei protege a mulher independentemente de ORIENTAÇÃO SEXUAL."]'::jsonb, 'Mulher lésbica agredida pela companheira é protegida pela lei.', '["Assertiva que condiciona a proteção da lei à orientação sexual da mulher erra."]'::jsonb, '[]'::jsonb, '["Art. 5º, parágrafo único"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária. O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares. Cabe à família, à sociedade e ao poder público criar as condições necessárias para o efetivo exercício desses direitos.', '["Rol de direitos a serem assegurados à mulher.","Políticas públicas para resguardar da negligência, discriminação, exploração, violência, crueldade e opressão.","Responsabilidade da família, da sociedade e do poder público."]'::jsonb, '["A responsabilidade é TRÍPLICE: família, sociedade e poder público."]'::jsonb, 'O poder público cria política de moradia para mulheres em situação de violência.', '["Assertiva que atribui apenas ao Estado o dever de criar as condições previstas no art. 3º erra: é também da família e da sociedade."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na interpretação da Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar.', '["Interpretação teleológica: fins sociais da lei.","Atenção às condições peculiares das mulheres em situação de violência."]'::jsonb, '["Regra de interpretação: fins sociais e condição peculiar da vítima."]'::jsonb, 'Na dúvida, o juiz interpreta a lei de modo a proteger a mulher em situação de violência.', '["Assertiva que manda interpretar a lei apenas pela literalidade, sem os fins sociais, erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial, no âmbito da unidade doméstica (espaço de convívio permanente, com ou sem vínculo familiar, inclusive as esporadicamente agregadas), no âmbito da família (comunidade de indivíduos que são ou se consideram aparentados, por laços naturais, por afinidade ou por vontade expressa) ou em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação. As relações pessoais independem de orientação sexual.', '["Ação ou omissão BASEADA NO GÊNERO.","Consequências: morte, lesão, sofrimento físico, sexual ou psicológico, dano moral ou patrimonial.","I: unidade doméstica.","II: família.","III: relação íntima de afeto, independentemente de coabitação.","Independe de orientação sexual."]'::jsonb, '["Exige motivação de GÊNERO (vulnerabilidade da mulher).","Relação íntima de afeto: não exige coabitação (STJ).","A violência contra a trabalhadora doméstica pode configurar o inciso I."]'::jsonb, 'Agressão do ex-namorado, que nunca coabitou com a vítima, por ciúmes, é violência doméstica.', '["Assertiva que exige coabitação para configurar a relação íntima de afeto erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos.', '["Violência doméstica e familiar é violação de direitos humanos."]'::jsonb, '["Reconhecimento expresso do caráter de violação de direitos humanos."]'::jsonb, 'A agressão do marido contra a esposa é tratada como violação de direitos humanos.', '["Assertiva que trata a violência doméstica como questão meramente privada erra: é violação de direitos humanos."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São formas de violência doméstica e familiar contra a mulher, entre outras: a violência física (conduta que ofenda a integridade ou a saúde corporal); a violência psicológica (conduta que cause dano emocional, diminuição da autoestima ou prejudique o desenvolvimento, ou vise degradar ou controlar ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de intimidade, ridicularização, exploração e limitação do direito de ir e vir); a violência sexual (constranger a presenciar, manter ou participar de relação sexual não desejada, mediante intimidação, ameaça, coação ou força, impedir o uso de método contraceptivo, forçar ao matrimônio, gravidez, aborto ou prostituição); a violência patrimonial (retenção, subtração ou destruição de objetos, instrumentos de trabalho, documentos, bens, valores e direitos); e a violência moral (calúnia, difamação ou injúria).', '["I: violência física.","II: violência psicológica.","III: violência sexual.","IV: violência patrimonial.","V: violência moral (calúnia, difamação, injúria).","Rol exemplificativo (''entre outras'')."]'::jsonb, '["ATUALIZAÇÃO: a redação do inciso II veio da Lei nº 13.772, de 2018 (violação da intimidade).","O rol é EXEMPLIFICATIVO."]'::jsonb, 'Ex-companheiro que retém os documentos pessoais da vítima pratica violência patrimonial.', '["Assertiva que considera taxativo o rol de formas de violência do art. 7º erra: o texto diz ''entre outras''."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A política pública que visa coibir a violência doméstica e familiar contra a mulher far-se-á por meio de um conjunto articulado de ações da União, dos Estados, do Distrito Federal e dos Municípios e de ações não governamentais, tendo por diretrizes a integração operacional do Judiciário, do Ministério Público e da Defensoria com as áreas de segurança pública, assistência social, saúde, educação, trabalho e habitação; a promoção de estudos e estatísticas com perspectiva de gênero e raça ou etnia; o respeito, nos meios de comunicação, dos valores éticos e sociais, coibindo papéis estereotipados; e a implementação de atendimento policial especializado, em particular nas Delegacias de Atendimento à Mulher, entre outras.', '["Ações articuladas de todos os entes e de organizações não governamentais.","Integração do sistema de justiça com segurança, assistência, saúde, educação, trabalho e habitação.","Estudos e estatísticas com perspectiva de gênero e raça ou etnia.","Combate a papéis estereotipados nos meios de comunicação.","Atendimento policial especializado."]'::jsonb, '["Rol de diretrizes com várias frentes; confira o texto integral."]'::jsonb, 'A Delegacia de Atendimento à Mulher presta atendimento policial especializado.', '["Assertiva que restringe a política pública a ações da União erra: é articulada entre os entes e organizações não governamentais."]'::jsonb, '[]'::jsonb, '["Art. 12-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A assistência à mulher em situação de violência doméstica e familiar será prestada em caráter prioritário no SUS e no Susp, de forma articulada, conforme a Lei Orgânica da Assistência Social e outras políticas públicas, e emergencialmente, quando for o caso. O juiz determinará, por prazo certo, a inclusão da mulher no cadastro de programas assistenciais do governo federal, estadual e municipal. O juiz assegurará à mulher, para preservar sua integridade, o acesso prioritário à remoção quando servidora pública; a manutenção do vínculo trabalhista, quando necessário o afastamento do local de trabalho, por até seis meses; e o encaminhamento à assistência judiciária, inclusive para ação de separação judicial, divórcio, anulação de casamento ou dissolução de união estável.', '["Assistência prioritária no SUS e no Susp.","Inclusão em programas assistenciais por prazo certo.","Remoção prioritária da servidora pública.","Manutenção do vínculo trabalhista por até seis meses.","Encaminhamento à assistência judiciária."]'::jsonb, '["ATUALIZAÇÃO: caput com redação da Lei nº 14.887, de 2024; inciso III do §2º incluído pela Lei nº 13.894, de 2019.","Afastamento do trabalho: até SEIS MESES, com manutenção do vínculo."]'::jsonb, 'A servidora pública vítima tem acesso prioritário à remoção, para preservar sua integridade.', '["Assertiva que limita a manutenção do vínculo trabalhista a três meses erra: é por até seis meses."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na hipótese da iminência ou da prática de violência doméstica e familiar contra a mulher, a autoridade policial que tomar conhecimento da ocorrência adotará, de imediato, as providências legais cabíveis. Aplica-se o disposto também ao descumprimento de medida protetiva de urgência deferida.', '["Iminência ou prática de violência: providências imediatas pela autoridade policial.","Vale também para o descumprimento de medida protetiva."]'::jsonb, '["Atua-se já na IMINÊNCIA da violência."]'::jsonb, 'A polícia é acionada por ameaça iminente e adota, de imediato, as providências legais.', '["Assertiva que restringe a atuação policial à violência já consumada erra: abrange a iminência e o descumprimento de medida."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É direito da mulher em situação de violência doméstica e familiar o atendimento policial e pericial especializado, ininterrupto e prestado por servidores, preferencialmente do sexo feminino, previamente capacitados. A inquirição da mulher ou de testemunha obedecerá às diretrizes de salvaguarda da integridade física, psíquica e emocional da depoente; garantia de que, em nenhuma hipótese, a mulher, familiares e testemunhas terão contato direto com investigados ou suspeitos e pessoas a eles relacionadas; e não revitimização, evitando sucessivas inquirições sobre o mesmo fato nos âmbitos criminal, cível e administrativo e questionamentos sobre a vida privada.', '["Atendimento policial e pericial especializado, ininterrupto, por servidores preferencialmente mulheres.","Inquirição com salvaguarda da integridade.","Sem contato direto com o investigado.","Não revitimização."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.505, de 2017.","Servidores PREFERENCIALMENTE do sexo feminino."]'::jsonb, 'A vítima é ouvida em sala reservada, sem contato com o suspeito, e não repete o relato a cada instituição.', '["Assertiva que permite o contato direto da vítima com o investigado na inquirição erra."]'::jsonb, '[{"termo":"Revitimização","significado":"Nova exposição da vítima ao sofrimento por repetidos relatos ou atendimentos inadequados."}]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-10-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No atendimento à mulher em situação de violência doméstica e familiar, a autoridade policial deverá, entre outras providências, garantir proteção policial, quando necessário, comunicando de imediato ao Ministério Público e ao Judiciário; encaminhar a ofendida ao hospital ou posto de saúde e ao Instituto Médico Legal; fornecer transporte para a ofendida e seus dependentes para abrigo ou local seguro, quando houver risco de vida; acompanhar a ofendida, se necessário, para a retirada de seus pertences; e informar à ofendida os direitos conferidos pela Lei e os serviços disponíveis, inclusive de assistência judiciária. Verificados indícios de redução a condição análoga à de escravo ou outra forma de violência contra a trabalhadora doméstica, a autoridade policial comunicará, em até 48 horas, a unidade regional do Ministério do Trabalho e Emprego e o Ministério Público do Trabalho.', '["Proteção policial, com comunicação imediata ao MP e ao Judiciário.","Encaminhamento a hospital e IML.","Transporte para abrigo ou local seguro.","Acompanhar a retirada de pertences.","Informar os direitos e serviços.","Trabalhadora doméstica: comunicação em até 48 horas ao Ministério do Trabalho e ao MPT."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído na proteção da trabalhadora doméstica (prazo de 48 horas).","Rol exemplificativo (''entre outras'')."]'::jsonb, 'A autoridade acompanha a vítima à residência para retirar seus pertences, com segurança.', '["Assertiva que fixa em 24 horas a comunicação sobre a trabalhadora doméstica ao Ministério do Trabalho erra: são 48 horas."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todos os casos de violência doméstica e familiar contra a mulher, feito o registro da ocorrência, deverá a autoridade policial adotar, de imediato, os procedimentos de ouvir a ofendida, lavrar o boletim de ocorrência e tomar a representação a termo, se apresentada; colher todas as provas; remeter, no prazo de 48 horas, expediente apartado ao juiz com o pedido da ofendida para a concessão de medidas protetivas de urgência; determinar o exame de corpo de delito e outros exames periciais; ouvir o agressor e as testemunhas; ordenar a identificação do agressor e juntar sua folha de antecedentes, indicando a existência de mandado de prisão ou outras ocorrências; e verificar se o agressor possui registro de porte ou posse de arma de fogo, juntando a informação e notificando a instituição responsável, entre outras providências.', '["Ouvir a ofendida, lavrar o boletim e tomar a representação a termo.","Colher provas.","Remeter ao juiz, em 48 horas, o pedido de medidas protetivas.","Exame de corpo de delito.","Ouvir o agressor e testemunhas.","Identificar o agressor e juntar antecedentes.","Verificar registro de arma de fogo do agressor."]'::jsonb, '["Prazo de 48 HORAS para remeter ao juiz o pedido de medidas protetivas.","Verificação de registro de arma de fogo foi acrescentada pela legislação posterior."]'::jsonb, 'Em 48 horas, o delegado envia ao juiz o pedido de medida protetiva da vítima.', '["Assertiva que fixa em 24 horas a remessa do pedido de medidas protetivas ao juiz erra: são 48 horas."]'::jsonb, '[]'::jsonb, '["Art. 18","Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Estados e o Distrito Federal, na formulação de suas políticas e planos de atendimento à mulher em situação de violência doméstica e familiar, darão prioridade, no âmbito da Polícia Civil, à criação de Delegacias Especializadas de Atendimento à Mulher (Deams), de Núcleos Investigativos de Feminicídio e de equipes especializadas para o atendimento e a investigação das violências graves contra a mulher.', '["Prioridade à criação de Deams, de Núcleos Investigativos de Feminicídio e de equipes especializadas.","Dever dos Estados e do Distrito Federal, no âmbito da Polícia Civil."]'::jsonb, '["Cabe aos ESTADOS e ao DF, na Polícia Civil."]'::jsonb, 'O Estado cria um núcleo especializado para investigar feminicídios.', '["Assertiva que atribui aos Municípios a criação das Deams erra: é dos Estados e do Distrito Federal."]'::jsonb, '[{"termo":"Deam","significado":"Delegacia Especializada de Atendimento à Mulher."}]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-12-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a existência de risco atual ou iminente à vida ou à integridade física, sexual, psicológica, moral ou patrimonial da mulher em situação de violência doméstica e familiar, ou de seus dependentes, o agressor será imediatamente afastado do lar, domicílio ou local de convivência com a ofendida pela autoridade judicial; pelo delegado de polícia, quando o Município não for sede de comarca; ou pelo policial, quando o Município não for sede de comarca e não houver delegado disponível no momento da denúncia. Nas hipóteses do delegado e do policial, o juiz será comunicado em até 24 horas e decidirá, em igual prazo, sobre a manutenção ou a revogação da medida, dando ciência ao Ministério Público. Nos casos de risco à integridade física da ofendida ou à efetividade da medida protetiva, não será concedida liberdade provisória ao preso.', '["Afastamento imediato do agressor em caso de risco atual ou iminente.","Quem afasta: juiz; delegado, se o Município não é sede de comarca; policial, se também não há delegado.","Juiz comunicado em 24 horas e decide em igual prazo.","Sem liberdade provisória ao preso em caso de risco à integridade física ou à efetividade da medida."]'::jsonb, '["ATUALIZAÇÃO: caput com redação da Lei nº 15.411, de 2026; incisos e parágrafos incluídos pela Lei nº 13.827, de 2019.","Prazo de 24 HORAS para o juiz ser comunicado e decidir."]'::jsonb, 'Em município sem sede de comarca, o delegado afasta o agressor e comunica o juiz em 24 horas.', '["Assertiva que permite ao policial afastar o agressor sempre que há delegado disponível, no município sem comarca, erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-12-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a existência de risco atual ou iminente à vida ou à integridade física ou psicológica da mulher em situação de violência doméstica e familiar, ou de seus dependentes, o agressor será imediatamente submetido à monitoração eletrônica pela autoridade judicial ou pelo delegado de polícia, quando o Município não for sede de comarca. Na hipótese do delegado, o juiz será comunicado no prazo máximo de 24 horas e decidirá, em igual prazo, sobre a manutenção ou a revogação da medida, dando ciência ao Ministério Público.', '["Monitoração eletrônica imediata do agressor em caso de risco atual ou iminente.","Autoridade judicial ou delegado (Município sem comarca).","Juiz comunicado em 24 horas e decide em igual prazo."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 15.383, de 2026 (monitoração eletrônica)."]'::jsonb, 'O delegado, em Município sem sede de comarca, determina a tornozeleira e comunica o juiz em 24 horas.', '["Assertiva que permite ao policial, e não ao delegado, aplicar a monitoração eletrônica nesse caso erra."]'::jsonb, '[]'::jsonb, '["Art. 12-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-12-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao processo, ao julgamento e à execução das causas cíveis e criminais decorrentes da prática de violência doméstica e familiar contra a mulher aplicar-se-ão as normas dos Códigos de Processo Penal e Processo Civil e da legislação específica relativa à criança, ao adolescente e ao idoso que não conflitarem com o estabelecido na Lei.', '["Aplicam-se, subsidiariamente, o CPP e o CPC.","Também a legislação da criança, do adolescente e do idoso, se não conflitar com a lei."]'::jsonb, '["Aplicação subsidiária."]'::jsonb, 'Na lacuna da Lei Maria da Penha, aplica-se o Código de Processo Penal.', '["Assertiva que exclui a aplicação do Código de Processo Penal à violência doméstica erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Juizados de Violência Doméstica e Familiar contra a Mulher, órgãos da Justiça Ordinária com competência cível e criminal, poderão ser criados pela União, no Distrito Federal e nos Territórios, e pelos Estados, para o processo, o julgamento e a execução das causas decorrentes da prática de violência doméstica e familiar contra a mulher. Os atos processuais poderão realizar-se em horário noturno, conforme dispuserem as normas de organização judiciária.', '["Juizados são órgãos da Justiça ORDINÁRIA, com competência cível e criminal.","Podem ser criados pela União (DF e Territórios) e pelos Estados.","Atos processuais podem ser em horário noturno."]'::jsonb, '["Competência CÍVEL e CRIMINAL (competência híbrida).","Não se confundem com os Juizados Especiais Criminais."]'::jsonb, 'O Juizado de Violência Doméstica julga a ação penal e decide sobre medidas cíveis, como alimentos provisórios.', '["Assertiva que atribui ao Juizado de Violência Doméstica competência apenas criminal erra: é cível e criminal."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ofendida tem a opção de propor ação de divórcio ou de dissolução de união estável no Juizado de Violência Doméstica e Familiar contra a Mulher. Exclui-se da competência dos Juizados a pretensão relacionada à partilha de bens. Iniciada a situação de violência doméstica e familiar após o ajuizamento da ação de divórcio ou de dissolução de união estável, a ação terá preferência no juízo onde estiver.', '["Opção de propor divórcio ou dissolução de união estável no Juizado de Violência Doméstica.","A partilha de bens fica FORA da competência do Juizado.","Violência posterior ao ajuizamento: preferência da ação no juízo onde estiver."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.894, de 2019.","Partilha de bens: não é do Juizado."]'::jsonb, 'A vítima ajuíza o divórcio no Juizado de Violência Doméstica, mas a partilha segue para a vara de família.', '["Assertiva que inclui a partilha de bens na competência do Juizado de Violência Doméstica erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-14-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É competente, por opção da ofendida, para os processos cíveis regidos pela Lei, o Juizado do seu domicílio ou de sua residência; do lugar do fato em que se baseou a demanda; ou do domicílio do agressor.', '["Opção da ofendida: domicílio ou residência, lugar do fato ou domicílio do agressor."]'::jsonb, '["A escolha do foro cabe à OFENDIDA, nos processos CÍVEIS."]'::jsonb, 'A vítima escolhe ajuizar a ação cível no Juizado do seu próprio domicílio.', '["Assertiva que fixa o foro cível exclusivamente no domicílio do agressor erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas ações penais públicas condicionadas à representação da ofendida, só será admitida a renúncia à representação perante o juiz, em audiência especialmente designada com tal finalidade, antes do recebimento da denúncia e ouvido o Ministério Público. A audiência tem por objetivo confirmar a retratação da vítima, e não a representação, e somente será designada pelo juiz mediante manifestação expressa de seu desejo de se retratar, apresentada por escrito ou oralmente antes do recebimento da denúncia, devendo a retratação ser registrada nos autos.', '["Renúncia (retratação) à representação só perante o juiz, em audiência especial.","Antes do recebimento da denúncia e ouvido o MP.","A audiência confirma a RETRATAÇÃO, e não a representação.","Só é designada se a vítima manifestar expressamente o desejo de se retratar."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído pela Lei nº 15.380, de 2026.","Há discussão no STF (ADI 7267)."]'::jsonb, 'A vítima manifesta por escrito o desejo de se retratar, e o juiz designa a audiência antes de receber a denúncia.', '["Assertiva que determina a audiência para confirmar a representação, e não a retratação, erra."]'::jsonb, '[]'::jsonb, '["Art. 16-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa ou de representação se não o exerce no prazo de 12 meses, contado do dia em que veio a saber quem é o autor do crime, ou, no caso do art. 100, §3º, do Código Penal, do dia em que se esgota o prazo para oferecimento da denúncia.', '["Decadência da queixa ou representação em 12 meses.","Contados da ciência da autoria."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 15.438, de 2026.","Prazo especial de 12 meses (o geral do CPP é de seis meses)."]'::jsonb, 'A vítima de ameaça tem 12 meses, desde que soube a autoria, para representar.', '["Assertiva que aplica à violência doméstica o prazo decadencial geral de seis meses erra: são 12 meses."]'::jsonb, '[]'::jsonb, '["Art. 38 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-16-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedada a aplicação, nos casos de violência doméstica e familiar contra a mulher, de penas de cesta básica ou outras de prestação pecuniária, bem como a substituição de pena que implique o pagamento isolado de multa.', '["Vedadas cestas básicas e outras prestações pecuniárias.","Vedada a substituição que implique pagamento isolado de multa."]'::jsonb, '["Vedação a penas pecuniárias banalizadoras."]'::jsonb, 'O juiz não pode substituir a pena do agressor por doação de cestas básicas.', '["Assertiva que admite a substituição da pena do agressor por cestas básicas erra."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O nome da ofendida ficará sob sigilo nos processos em que se apuram crimes praticados no contexto de violência doméstica e familiar contra a mulher. O sigilo não abrange o nome do autor do fato, tampouco os demais dados do processo.', '["Sigilo do NOME da ofendida.","Não alcança o nome do autor nem os demais dados do processo."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.857, de 2024.","O sigilo é só do nome da vítima."]'::jsonb, 'O processo é público, mas o nome da vítima é mantido em sigilo.', '["Assertiva que decreta sigilo de todo o processo de violência doméstica erra: só o nome da ofendida é sigiloso."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-17-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebido o expediente com o pedido da ofendida, caberá ao juiz, no prazo de 48 horas, conhecer do expediente e do pedido e decidir sobre as medidas protetivas de urgência; determinar o encaminhamento da ofendida ao órgão de assistência judiciária, inclusive para ação de separação, divórcio, anulação de casamento ou dissolução de união estável; comunicar ao Ministério Público; e determinar a apreensão imediata de arma de fogo sob a posse do agressor.', '["Prazo de 48 horas para o juiz decidir sobre as medidas protetivas.","Encaminhamento à assistência judiciária.","Comunicação ao MP.","Apreensão imediata de arma de fogo do agressor."]'::jsonb, '["ATUALIZAÇÃO: inciso IV incluído pela Lei nº 13.880, de 2019 (apreensão de arma).","Prazo de 48 HORAS."]'::jsonb, 'Em 48 horas, o juiz decide as medidas e determina a apreensão da arma do agressor.', '["Assertiva que fixa em 24 horas o prazo do juiz para decidir sobre as medidas protetivas erra: são 48 horas."]'::jsonb, '[]'::jsonb, '["Art. 12, III","Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas protetivas de urgência poderão ser concedidas pelo juiz, a requerimento do Ministério Público ou a pedido da ofendida, de imediato, independentemente de audiência das partes e de manifestação do Ministério Público, devendo este ser prontamente comunicado. Serão aplicadas isolada ou cumulativamente, e poderão ser substituídas a qualquer tempo por outras de maior eficácia. O juiz poderá, a pedido, conceder novas medidas ou rever as já concedidas, ouvido o MP. Serão concedidas em juízo de cognição sumária a partir do depoimento da ofendida perante a autoridade policial ou de suas alegações escritas, e poderão ser indeferidas no caso de avaliação pela autoridade de inexistência de risco à ofendida ou a seus dependentes.', '["Concessão a requerimento do MP ou pedido da ofendida.","De imediato, sem audiência das partes nem manifestação prévia do MP.","Isoladas ou cumuladas; substituíveis por outras mais eficazes.","Cognição sumária, com base no depoimento da ofendida ou em alegações escritas."]'::jsonb, '["ATUALIZAÇÃO: §4º incluído pela Lei nº 14.550, de 2023: as medidas não dependem de tipificação penal, de inquérito ou de processo.","Concessão IMEDIATA, sem audiência das partes."]'::jsonb, 'O juiz concede liminarmente a medida protetiva com base no depoimento da vítima, sem ouvir o agressor.', '["Assertiva que exige a oitiva prévia do agressor para conceder medida protetiva erra: ela pode ser concedida de imediato."]'::jsonb, '[]'::jsonb, '["Art. 18","Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase do inquérito policial ou da instrução criminal, caberá a prisão preventiva do agressor, decretada pelo juiz, de ofício, a requerimento do Ministério Público ou mediante representação da autoridade policial. O juiz poderá revogar a prisão preventiva se, no curso do processo, verificar a falta de motivo para que subsista, bem como de novo decretá-la, se sobrevierem razões que a justifiquem.', '["Preventiva do agressor em qualquer fase do inquérito ou da instrução.","Decretada de ofício, a requerimento do MP ou por representação policial.","Revogável se faltar motivo, e novamente decretável."]'::jsonb, '["O texto permite a decretação DE OFÍCIO; o CPP, com a reforma de 2019, restringe a decretação de ofício (debate doutrinário)."]'::jsonb, 'O juiz decreta a preventiva do agressor que ameaça a vítima.', '["Assertiva que restringe a preventiva ao momento da instrução, excluindo o inquérito, erra: cabe em qualquer fase."]'::jsonb, '[]'::jsonb, '["Art. 313, III do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ofendida deverá ser notificada dos atos processuais relativos ao agressor, especialmente dos pertinentes ao ingresso e à saída da prisão, sem prejuízo da intimação do advogado constituído ou do defensor público. A ofendida não poderá entregar intimação ou notificação ao agressor.', '["Notificação da ofendida dos atos relativos ao agressor, especialmente prisão e soltura.","Sem prejuízo da intimação do advogado ou defensor.","A ofendida NÃO entrega intimação ao agressor."]'::jsonb, '["Vedado à vítima entregar intimação ou notificação ao agressor."]'::jsonb, 'A vítima é avisada da saída do agressor da prisão, e o oficial de justiça notifica o agressor.', '["Assertiva que permite à ofendida entregar a intimação ao agressor erra."]'::jsonb, '[]'::jsonb, '["Direitos do ofendido no CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constatada a prática de violência doméstica e familiar contra a mulher, o juiz poderá aplicar de imediato ao agressor, em conjunto ou separadamente, as seguintes medidas protetivas de urgência, entre outras: suspensão da posse ou restrição do porte de armas; afastamento do lar, domicílio ou local de convivência com a ofendida; proibição de determinadas condutas (aproximação da ofendida, de familiares e testemunhas, com limite mínimo de distância; contato por qualquer meio; frequentação de determinados lugares); restrição ou suspensão de visitas aos dependentes menores, ouvida a equipe multidisciplinar; prestação de alimentos provisionais ou provisórios; comparecimento do agressor a programas de recuperação e reeducação; e acompanhamento psicossocial do agressor.', '["I: suspensão da posse ou restrição do porte de armas.","II: afastamento do lar.","III: proibição de aproximação, contato e frequentação de lugares.","IV: restrição ou suspensão de visitas aos dependentes.","V: alimentos provisionais ou provisórios.","VI: programas de recuperação e reeducação.","VII: acompanhamento psicossocial."]'::jsonb, '["ATUALIZAÇÃO: incisos VI e VII incluídos pela Lei nº 13.984, de 2020.","Rol EXEMPLIFICATIVO (''entre outras'')."]'::jsonb, 'O juiz proíbe o agressor de se aproximar da vítima a menos de uma distância fixada e de contatá-la.', '["Assertiva que considera taxativo o rol de medidas protetivas do art. 22 erra: é exemplificativo."]'::jsonb, '[]'::jsonb, '["Art. 24-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá o juiz, quando necessário, sem prejuízo de outras medidas, encaminhar a ofendida e seus dependentes a programa oficial ou comunitário de proteção ou de atendimento; determinar a recondução da ofendida e de seus dependentes ao domicílio, após afastamento do agressor; determinar o afastamento da ofendida do lar, sem prejuízo dos direitos relativos a bens, guarda dos filhos e alimentos; determinar a separação de corpos; determinar a matrícula dos dependentes da ofendida em instituição de educação básica mais próxima do domicílio, independentemente da existência de vaga; e conceder à ofendida auxílio-aluguel, por período não superior a 6 meses.', '["Encaminhamento a programa de proteção.","Recondução ao domicílio após afastamento do agressor.","Afastamento da ofendida do lar, sem prejuízo de bens, guarda e alimentos.","Separação de corpos.","Matrícula dos dependentes, independentemente de vaga.","Auxílio-aluguel por até 6 meses."]'::jsonb, '["ATUALIZAÇÃO: inciso V incluído pela Lei nº 13.882, de 2019; inciso VI (auxílio-aluguel) pela Lei nº 14.674, de 2023.","Auxílio-aluguel: no máximo 6 meses."]'::jsonb, 'O juiz concede auxílio-aluguel por até seis meses a vítima em situação de vulnerabilidade.', '["Assertiva que fixa em 12 meses o prazo do auxílio-aluguel erra: é de até 6 meses."]'::jsonb, '[{"termo":"Separação de corpos","significado":"Afastamento dos cônjuges ou companheiros da convivência."}]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a proteção patrimonial dos bens da sociedade conjugal ou daqueles de propriedade particular da mulher, o juiz poderá determinar, liminarmente, entre outras medidas, a restituição de bens indevidamente subtraídos pelo agressor à ofendida; a proibição temporária para a celebração de atos e contratos de compra, venda e locação de propriedade em comum, salvo expressa autorização judicial; a suspensão das procurações conferidas pela ofendida ao agressor; e a prestação de caução provisória, mediante depósito judicial, por perdas e danos materiais decorrentes da violência. O juiz deverá oficiar ao cartório competente para os fins dos incisos II e III.', '["Restituição de bens subtraídos.","Proibição temporária de atos de compra, venda e locação de bens comuns.","Suspensão das procurações dadas ao agressor.","Caução provisória por perdas e danos.","Ofício ao cartório competente."]'::jsonb, '["Medidas de proteção PATRIMONIAL, concedidas liminarmente."]'::jsonb, 'O juiz suspende as procurações que a vítima havia conferido ao agressor.', '["Assertiva que impede o juiz de suspender procurações como medida protetiva patrimonial erra."]'::jsonb, '[]'::jsonb, '["Art. 7º, IV"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Descumprir decisão judicial que defere medidas protetivas de urgência previstas na Lei. Pena: reclusão de 2 a 5 anos e multa. A configuração do crime independe da competência civil ou criminal do juiz que deferiu as medidas. Na hipótese de prisão em flagrante, apenas a autoridade judicial poderá conceder fiança. O disposto não exclui a aplicação de outras sanções cabíveis. A pena será aumentada de 1/3 até a metade se o descumprimento decorrer da violação das áreas de exclusão monitoradas eletronicamente ou da remoção, violação ou alteração do dispositivo de monitoração sem autorização judicial.', '["Crime de descumprimento de medida protetiva.","Reclusão de 2 a 5 anos e multa.","Independe da competência do juiz que deferiu a medida.","Fiança só pelo juiz.","Aumento de 1/3 até a metade em violação de áreas monitoradas ou do dispositivo."]'::jsonb, '["ATUALIZAÇÃO: pena alterada para 2 a 5 anos pela Lei nº 14.994, de 2024; §4º incluído pela Lei nº 15.383, de 2026.","FIANÇA: só a autoridade judicial concede, e não o delegado.","A pena, na redação original (Lei nº 13.641, de 2018), era de detenção de 3 meses a 2 anos."]'::jsonb, 'O agressor se aproxima da vítima, descumprindo medida protetiva, e é preso em flagrante: só o juiz pode conceder a fiança.', '["Assertiva que permite ao delegado conceder fiança no crime do art. 24-A erra: apenas a autoridade judicial."]'::jsonb, '[]'::jsonb, '["Art. 22","Descumprimento de medidas protetivas no CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-24-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público intervirá, quando não for parte, nas causas cíveis e criminais decorrentes da violência doméstica e familiar contra a mulher.', '["O MP intervém, quando não for parte, nas causas cíveis e criminais."]'::jsonb, '["Atuação como fiscal da lei nas causas cíveis e criminais."]'::jsonb, 'Em ação cível de alimentos da vítima, o MP intervém como fiscal da lei.', '["Assertiva que restringe a intervenção do MP às causas criminais erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Ministério Público, sem prejuízo de outras atribuições, nos casos de violência doméstica e familiar contra a mulher, quando necessário, requisitar força policial e serviços públicos de saúde, de educação, de assistência social e de segurança, entre outros; fiscalizar os estabelecimentos públicos e particulares de atendimento à mulher, adotando de imediato as medidas administrativas ou judiciais cabíveis; e cadastrar os casos de violência doméstica e familiar contra a mulher.', '["Requisitar força policial e serviços públicos.","Fiscalizar estabelecimentos de atendimento à mulher.","Cadastrar os casos de violência."]'::jsonb, '["Três atribuições específicas, sem prejuízo de outras."]'::jsonb, 'O MP fiscaliza uma casa-abrigo e adota medida diante de irregularidade.', '["Assertiva que retira do MP a atribuição de cadastrar os casos de violência doméstica erra."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todos os atos processuais, cíveis e criminais, a mulher em situação de violência doméstica e familiar deverá estar acompanhada de advogado, ressalvado o previsto no art. 19 (concessão de medidas protetivas de urgência).', '["Acompanhamento por advogado em todos os atos processuais, cíveis e criminais.","Ressalva: o pedido de medidas protetivas do art. 19."]'::jsonb, '["Para pedir medida protetiva, NÃO é necessário advogado."]'::jsonb, 'A vítima pede a medida protetiva na delegacia, sem advogado, mas é assistida nos demais atos.', '["Assertiva que exige advogado para o pedido de medida protetiva erra: o art. 27 ressalva o art. 19."]'::jsonb, '[]'::jsonb, '["Art. 19","Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É garantido a toda mulher em situação de violência doméstica e familiar o acesso aos serviços de Defensoria Pública ou de Assistência Judiciária Gratuita, nos termos da lei, em sede policial e judicial, mediante atendimento específico e humanizado.', '["Acesso à Defensoria Pública ou à Assistência Judiciária Gratuita.","Em sede policial e judicial.","Atendimento específico e humanizado."]'::jsonb, '["Assistência garantida também na FASE POLICIAL."]'::jsonb, 'A vítima é atendida pela Defensoria Pública já na delegacia.', '["Assertiva que restringe a assistência jurídica à fase judicial erra: abrange a fase policial."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Juizados de Violência Doméstica e Familiar contra a Mulher que vierem a ser criados poderão contar com uma equipe de atendimento multidisciplinar, a ser integrada por profissionais especializados nas áreas psicossocial, jurídica e de saúde.', '["Equipe multidisciplinar nos Juizados.","Áreas psicossocial, jurídica e de saúde."]'::jsonb, '["Faculdade (''poderão contar'')."]'::jsonb, 'O Juizado conta com psicólogos, assistentes sociais e profissionais de saúde.', '["Assertiva que torna obrigatória a equipe multidisciplinar erra: é facultativa."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à equipe de atendimento multidisciplinar, entre outras atribuições, fornecer subsídios por escrito ao juiz, ao Ministério Público e à Defensoria Pública, mediante laudos ou verbalmente em audiência, e desenvolver trabalhos de orientação, encaminhamento, prevenção e outras medidas, voltados para a ofendida, o agressor e os familiares, com especial atenção às crianças e aos adolescentes.', '["Fornecer subsídios por escrito ou verbalmente ao juiz, ao MP e à Defensoria.","Orientação, encaminhamento e prevenção.","Voltados à ofendida, ao agressor e aos familiares, com atenção às crianças e adolescentes."]'::jsonb, '["Atende também o AGRESSOR e os familiares."]'::jsonb, 'A equipe elabora laudo psicossocial para subsidiar a decisão do juiz.', '["Assertiva que restringe o atendimento da equipe à vítima erra: abrange o agressor e os familiares."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a complexidade do caso exigir avaliação mais aprofundada, o juiz poderá determinar a manifestação de profissional especializado, mediante a indicação da equipe de atendimento multidisciplinar.', '["Caso complexo: juiz pode determinar a manifestação de profissional especializado.","Indicado pela equipe multidisciplinar."]'::jsonb, '["Indicação feita pela equipe multidisciplinar."]'::jsonb, 'O juiz pede avaliação de um psiquiatra indicado pela equipe.', '["Assertiva que dispensa a indicação pela equipe multidisciplinar do profissional especializado erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-31'
