insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Enquanto não estruturados os Juizados de Violência Doméstica e Familiar contra a Mulher, as varas criminais acumularão as competências cível e criminal para conhecer e julgar as causas decorrentes da prática de violência doméstica e familiar contra a mulher, observadas as previsões do Título IV da Lei, subsidiada pela legislação processual pertinente. Será garantido o direito de preferência, nas varas criminais, para o processo e o julgamento dessas causas.', '["Sem Juizado, as varas criminais acumulam competência cível e criminal.","Preferência para o processo e julgamento dessas causas."]'::jsonb, '["Regra transitória, com preferência de julgamento."]'::jsonb, 'Em comarca sem Juizado especializado, a vara criminal julga também as medidas cíveis.', '["Assertiva que remete as causas à vara cível, na ausência de Juizado, erra: as varas criminais acumulam as competências."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

