insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos crimes praticados com violência doméstica e familiar contra a mulher, independentemente da pena prevista, não se aplica a Lei nº 9.099, de 1995 (Juizados Especiais Criminais).', '["Não se aplica a Lei dos Juizados Especiais, independentemente da pena.","Afasta transação penal, suspensão condicional do processo e outros benefícios da Lei nº 9.099."]'::jsonb, '["O STF reconheceu a constitucionalidade do dispositivo.","Súmula do STJ: não cabe suspensão condicional do processo nesses crimes."]'::jsonb, 'Lesão corporal leve contra a esposa não admite transação penal.', '["Assertiva que admite a transação penal nos crimes de violência doméstica, por serem de menor potencial ofensivo, erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
