insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 313 do Código de Processo Penal passa a vigorar acrescido do inciso IV: se o crime envolver violência doméstica e familiar contra a mulher, nos termos da lei específica, para garantir a execução das medidas protetivas de urgência (admissão da prisão preventiva).', '["Acrescenta hipótese de prisão preventiva no CPP.","Crime com violência doméstica e familiar contra a mulher, para garantir a execução das medidas protetivas."]'::jsonb, '["A norma foi depois reorganizada: hoje consta do art. 313, III, do CPP."]'::jsonb, 'A preventiva é admitida para garantir o cumprimento das medidas protetivas.', '["Assertiva que impede a preventiva para garantir medidas protetivas erra."]'::jsonb, '[]'::jsonb, '["Art. 313 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A alínea f do inciso II do art. 61 do Código Penal passa a vigorar com a redação: com abuso de autoridade ou prevalecendo-se de relações domésticas, de coabitação ou de hospitalidade, ou com violência contra a mulher na forma da lei específica (circunstância agravante).', '["Agravante genérica: violência contra a mulher na forma da lei específica.","Também abuso de autoridade e relações domésticas, de coabitação ou hospitalidade."]'::jsonb, '["Circunstância AGRAVANTE do art. 61, II, f, do Código Penal."]'::jsonb, 'A agressão contra a esposa, prevalecendo-se da relação doméstica, atrai a agravante.', '["Assertiva que trata a violência contra a mulher como causa de aumento do art. 61 erra: é circunstância agravante."]'::jsonb, '[]'::jsonb, '["Art. 61 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-43'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 129 do Código Penal passa a vigorar com alterações: se a lesão for praticada contra ascendente, descendente, irmão, cônjuge ou companheiro, ou com quem conviva ou tenha convivido, ou prevalecendo-se o agente das relações domésticas, de coabitação ou de hospitalidade, a pena é de detenção de 3 meses a 3 anos; e, nessa hipótese, a pena será aumentada de um terço se o crime for cometido contra pessoa portadora de deficiência.', '["Lesão corporal doméstica: detenção de 3 meses a 3 anos.","Aumento de um terço se a vítima é pessoa com deficiência."]'::jsonb, '["O art. 129, §9º, foi posteriormente alterado por outras leis; confira a redação vigente do Código Penal."]'::jsonb, 'Lesão corporal leve contra a esposa configura o art. 129, §9º, do Código Penal.', '["Assertiva que fixa pena de reclusão para a lesão doméstica do art. 129, §9º, na redação da Lei Maria da Penha, erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 129 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'maria-penha' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 152 da Lei de Execução Penal passa a vigorar com o parágrafo único: nos casos de violência doméstica contra a mulher, o juiz poderá determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação.', '["Na execução, o juiz pode determinar o comparecimento do agressor a programas de recuperação e reeducação."]'::jsonb, '["Alteração da Lei de Execução Penal."]'::jsonb, 'O juiz da execução determina que o agressor frequente programa de reeducação.', '["Assertiva que torna obrigatório o programa para todo agressor, independentemente de decisão do juiz, erra: depende de determinação judicial."]'::jsonb, '[]'::jsonb, '["Art. 22, VI"]'::jsonb, 'under_review', 'claude'
